6670  char *fgets_from_mem(char* buf, int size, const char **position, const char *end)
  6671  {
  6672          char *new_pos;
  6673          int len = 0;
  6674
  6675          /* keep fgets behaviour */
  6676          if (size <= 0)
  6677                  return NULL;
  6678
  6679          /* EOF */
  6680          if (*position == end)
  6681                  return NULL;
  6682
  6683          size--; /* keep fgets behaviour, reads at most one less than size */
  6684          new_pos = memchr(*position, '\n', size);
  6685          if (new_pos) {
  6686                  /* '+1' to grab and copy '\n' at the end of line */
  6687                  len = (new_pos + 1) - *position;
  6688          } else {
  6689                  /* just copy either the given size, or the rest of the line
  6690                   * until the end
  6691                   */
  6692                  len = MIN((end - *position), size);
  6693          }
  6694
  6695          memcpy(buf, *position, len);
  6696          *(buf + len)  = '\0';
  6697          *position += len;
  6698
  6699          return buf;
  6700  }
